// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint8 times1, uint8 times2, uint96 amt1, uint96 amt2) public {
        uint256 t1 = times1 % 10 + 1;
        uint256 t2 = times2 % 10 + 1;
        uint256 amount1 = uint256(amt1) + 1;
        uint256 amount2 = uint256(amt2) + 1;
        Helper h = new Helper();
        address actor = address(h);

        vm.startPrank(actor);
        vm.deal(actor, amount1 * t1 + amount2 * t2 + 1 ether);
        for (uint256 i = 0; i < t1; i++) {
            c.addToBalance{value: amount1}();
        }
        for (uint256 i = 0; i < t2; i++) {
            c.addToBalance{value: amount2}();
        }
        vm.stopPrank();

        uint256 totalSent = t1 * amount1 + t2 * amount2;
        uint256 bal = c.getBalance(actor);
        assertTrue(bal >= totalSent);
    }
}

contract Helper {
    uint256 public totalReceived;
    receive() external payable {
        totalReceived += msg.value;
    }
}
